import { expect, test, type Page } from "@playwright/test";

const SETUP_STATUS_URL = "**/api/v1/auth/setup-status";
const SERVICE_UNAVAILABLE_TITLE = "Service temporarily unavailable";

async function mockSetupStatusRecovery(
  page: Page,
  recoveredStatus: {
    needs_setup: boolean;
    registration_enabled?: boolean;
  },
) {
  let requestCount = 0;

  await page.route(SETUP_STATUS_URL, (route) => {
    if (route.request().method() !== "GET") {
      return route.fallback();
    }

    requestCount += 1;
    if (requestCount === 1) {
      return route.fulfill({
        status: 503,
        contentType: "application/json",
        body: JSON.stringify({ detail: "Gateway unavailable" }),
      });
    }

    return route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(recoveredStatus),
    });
  });

  return () => requestCount;
}

test.describe("auth setup-status recovery", () => {
  test.beforeEach(async ({ page }) => {
    await page.route("**/api/v1/auth/providers", (route) =>
      route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({ providers: [] }),
      }),
    );
  });

  test("login restores registration after setup-status retry", async ({
    page,
  }) => {
    const getRequestCount = await mockSetupStatusRecovery(page, {
      needs_setup: false,
      registration_enabled: true,
    });

    await page.goto("/login");

    await expect(page.getByText(SERVICE_UNAVAILABLE_TITLE)).toBeVisible();
    await expect(page.getByRole("button", { name: "Sign In" })).toBeEnabled();
    await expect(
      page.getByRole("button", { name: /Don't have an account/i }),
    ).toHaveCount(0);
    expect(getRequestCount()).toBe(1);

    await page.getByRole("button", { name: "Try again" }).click();

    await expect
      .poll(getRequestCount, { message: "setup-status should be retried" })
      .toBe(2);
    await expect(page.getByText(SERVICE_UNAVAILABLE_TITLE)).toBeHidden();
    await expect(
      page.getByRole("button", { name: /Don't have an account/i }),
    ).toBeVisible();
  });

  test("setup restores the administrator form after setup-status retry", async ({
    page,
  }) => {
    const getRequestCount = await mockSetupStatusRecovery(page, {
      needs_setup: true,
    });

    await page.goto("/setup");

    await expect(page.getByText(SERVICE_UNAVAILABLE_TITLE)).toBeVisible();
    await expect(page.getByRole("button", { name: "Try again" })).toBeVisible();
    expect(getRequestCount()).toBe(1);

    await page.getByRole("button", { name: "Try again" }).click();

    await expect
      .poll(getRequestCount, { message: "setup-status should be retried" })
      .toBe(2);
    await expect(page.getByText(SERVICE_UNAVAILABLE_TITLE)).toBeHidden();
    await expect(
      page.getByRole("button", { name: "Create Admin Account" }),
    ).toBeVisible();
    await expect(page.getByRole("textbox", { name: "Email" })).toBeVisible();
  });
});

import { afterEach, describe, expect, rs, test } from "@rstest/core";

import { AUTH_REQUEST_TIMEOUT_MS } from "@/core/auth/constants";
import {
  canCreateRegularAccount,
  fetchSetupStatus,
  isSystemAlreadyInitializedError,
  setupStatusFetchInit,
} from "@/core/auth/setup";

function pendingUntilAborted(signal: AbortSignal): Promise<Response> {
  return new Promise((_resolve, reject) => {
    signal.addEventListener(
      "abort",
      () => {
        reject(
          signal.reason instanceof Error
            ? signal.reason
            : new Error("The request was aborted"),
        );
      },
      { once: true },
    );
  });
}

function requestSignal(init?: RequestInit): AbortSignal {
  if (!init?.signal) {
    throw new Error("Expected fetch to receive an AbortSignal");
  }
  return init.signal;
}

describe("auth setup helpers", () => {
  afterEach(() => {
    rs.useRealTimers();
    rs.unstubAllGlobals();
  });

  test("setup-status requests bypass browser caches", () => {
    expect(setupStatusFetchInit).toMatchObject({
      cache: "no-store",
      credentials: "include",
    });
  });

  test("fetchSetupStatus uses the shared no-store request options", async () => {
    const fetchMock = rs.fn((_input: RequestInfo | URL, _init?: RequestInit) =>
      Promise.resolve(
        new Response(JSON.stringify({ needs_setup: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
      ),
    );
    rs.stubGlobal("fetch", fetchMock);

    await expect(fetchSetupStatus()).resolves.toEqual({ needs_setup: true });
    expect(fetchMock).toHaveBeenCalledWith(
      "/api/v1/auth/setup-status",
      expect.objectContaining(setupStatusFetchInit),
    );
    expect(fetchMock.mock.calls[0]?.[1]?.signal).toBeInstanceOf(AbortSignal);
  });

  test("aborts a setup-status request that remains pending", async () => {
    rs.useFakeTimers();
    const fetchMock = rs.fn((_input: RequestInfo | URL, init?: RequestInit) =>
      pendingUntilAborted(requestSignal(init)),
    );
    rs.stubGlobal("fetch", fetchMock);

    const request = fetchSetupStatus();
    const rejection = expect(request).rejects.toMatchObject({
      name: "AbortError",
    });

    await rs.advanceTimersByTimeAsync(AUTH_REQUEST_TIMEOUT_MS);
    await rejection;

    expect(fetchMock.mock.calls[0]![1]!.signal!.aborted).toBe(true);
  });

  test("clears the timeout after a successful setup-status response", async () => {
    rs.useFakeTimers();
    const signals: AbortSignal[] = [];
    const fetchMock = rs.fn((_input: RequestInfo | URL, init?: RequestInit) => {
      signals.push(requestSignal(init));
      return Promise.resolve(
        new Response(JSON.stringify({ needs_setup: false }), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
      );
    });
    rs.stubGlobal("fetch", fetchMock);

    await expect(fetchSetupStatus()).resolves.toEqual({ needs_setup: false });
    await rs.advanceTimersByTimeAsync(AUTH_REQUEST_TIMEOUT_MS);

    expect(signals[0]!.aborted).toBe(false);
  });

  test("a retry uses a fresh signal after the first request times out", async () => {
    rs.useFakeTimers();
    const signals: AbortSignal[] = [];
    const fetchMock = rs.fn((_input: RequestInfo | URL, init?: RequestInit) => {
      const signal = requestSignal(init);
      signals.push(signal);
      if (signals.length === 1) {
        return pendingUntilAborted(signal);
      }
      return Promise.resolve(
        new Response(JSON.stringify({ needs_setup: true }), {
          status: 200,
          headers: { "Content-Type": "application/json" },
        }),
      );
    });
    rs.stubGlobal("fetch", fetchMock);

    const firstRequest = fetchSetupStatus();
    const firstRejection = expect(firstRequest).rejects.toMatchObject({
      name: "AbortError",
    });
    await rs.advanceTimersByTimeAsync(AUTH_REQUEST_TIMEOUT_MS);
    await firstRejection;

    await expect(fetchSetupStatus()).resolves.toEqual({ needs_setup: true });

    expect(signals).toHaveLength(2);
    expect(signals[1]!).not.toBe(signals[0]!);
    expect(signals[0]!.aborted).toBe(true);
    expect(signals[1]!.aborted).toBe(false);
  });

  test("preserves setup-status HTTP errors", async () => {
    rs.stubGlobal(
      "fetch",
      rs.fn(() => Promise.resolve(new Response(null, { status: 503 }))),
    );

    await expect(fetchSetupStatus()).rejects.toThrow(
      "setup-status failed: 503",
    );
  });

  test("regular sign-up is disabled only while setup is required or unknown", () => {
    expect(canCreateRegularAccount({ checked: false, status: null })).toBe(
      false,
    );
    expect(
      canCreateRegularAccount({
        checked: true,
        status: { needs_setup: true },
      }),
    ).toBe(false);
    expect(
      canCreateRegularAccount({
        checked: true,
        status: { needs_setup: false },
      }),
    ).toBe(true);
    expect(canCreateRegularAccount({ checked: true, status: null })).toBe(true);
  });

  test("regular sign-up follows the gateway's registration_enabled flag", () => {
    expect(
      canCreateRegularAccount({
        checked: true,
        status: { needs_setup: false, registration_enabled: false },
      }),
    ).toBe(false);
    expect(
      canCreateRegularAccount({
        checked: true,
        status: { needs_setup: false, registration_enabled: true },
      }),
    ).toBe(true);
    // Older Gateways omit the field; absent must not hide the signup entry.
    expect(
      canCreateRegularAccount({
        checked: true,
        status: { needs_setup: false },
      }),
    ).toBe(true);
  });

  test("detects already-initialized setup conflicts", () => {
    expect(
      isSystemAlreadyInitializedError({
        detail: {
          code: "system_already_initialized",
          message: "System already initialized",
        },
      }),
    ).toBe(true);

    expect(
      isSystemAlreadyInitializedError({
        detail: {
          code: "invalid_credentials",
          message: "Wrong password",
        },
      }),
    ).toBe(false);
  });
});

"""Tests for MCP OAuth support."""

from __future__ import annotations

import asyncio
import logging
import threading
from typing import Any

import pytest

from deerflow.config.extensions_config import ExtensionsConfig
from deerflow.mcp.oauth import OAuthTokenManager, build_oauth_tool_interceptor, get_initial_oauth_headers


class _MockResponse:
    def __init__(self, payload: dict[str, Any]):
        self._payload = payload

    def raise_for_status(self) -> None:
        return None

    def json(self) -> dict[str, Any]:
        return self._payload


class _MockAsyncClient:
    def __init__(self, payload: dict[str, Any], post_calls: list[dict[str, Any]], **kwargs):
        self._payload = payload
        self._post_calls = post_calls

    async def __aenter__(self):
        return self

    async def __aexit__(self, exc_type, exc, tb):
        return False

    async def post(self, url: str, data: dict[str, Any]):
        self._post_calls.append({"url": url, "data": data})
        return _MockResponse(self._payload)


def test_oauth_token_manager_fetches_and_caches_token(monkeypatch):
    post_calls: list[dict[str, Any]] = []

    def _client_factory(*args, **kwargs):
        return _MockAsyncClient(
            payload={
                "access_token": "token-123",
                "token_type": "Bearer",
                "expires_in": 3600,
            },
            post_calls=post_calls,
            **kwargs,
        )

    monkeypatch.setattr("httpx.AsyncClient", _client_factory)

    config = ExtensionsConfig.model_validate(
        {
            "mcpServers": {
                "secure-http": {
                    "enabled": True,
                    "type": "http",
                    "url": "https://api.example.com/mcp",
                    "oauth": {
                        "enabled": True,
                        "token_url": "https://auth.example.com/oauth/token",
                        "grant_type": "client_credentials",
                        "client_id": "client-id",
                        "client_secret": "client-secret",
                    },
                }
            }
        }
    )

    manager = OAuthTokenManager.from_extensions_config(config)

    first = asyncio.run(manager.get_authorization_header("secure-http"))
    second = asyncio.run(manager.get_authorization_header("secure-http"))

    assert first == "Bearer token-123"
    assert second == "Bearer token-123"
    assert len(post_calls) == 1
    assert post_calls[0]["url"] == "https://auth.example.com/oauth/token"
    assert post_calls[0]["data"]["grant_type"] == "client_credentials"


